<script>(function(){var si=document.getElementById('homeProductSearch'),cs=document.querySelectorAll('#homeProductGrid .product-card');function f(){var t=si.value.trim().toLowerCase(),vc=0;cs.forEach(function(c){var n=c.getAttribute('data-product-name')||'';var ne=c.querySelector('.product-name');if(ne)n=ne.innerText.toLowerCase();var m=t===''||n.indexOf(t)!==-1;c.style.display=m?'':'none';if(m)vc++;});var nm=document.getElementById('noProductMatchMsg'),g=document.getElementById('homeProductGrid');if(vc===0&&t!==''){if(!nm){nm=document.createElement('div');nm.id='noProductMatchMsg';nm.style.cssText='text-align:center;padding:40px 20px;color:#5f6368;font-size:1rem;grid-column:1/-1';nm.innerText='No furniture found matching \"'+t+'\".';g.appendChild(nm);}else{nm.style.display='block';}}else if(nm){nm.style.display='none';}}if(si){si.addEventListener('input',f);f();}var tr=document.getElementById('accountTrigger'),dd=document.getElementById('accountDropdown');if(tr&&dd){tr.addEventListener('click',function(e){e.stopPropagation();dd.classList.toggle('show');});document.addEventListener('click',function(e){if(!tr.contains(e.target)&&!dd.contains(e.target))dd.classList.remove('show');});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&dd.classList.contains('show'))dd.classList.remove('show');});}})();</script></body></html>
